INSERT INTO "Book" (id,title,description,level,"isPublished","trackKey","cefrTier") VALUES ('a0000000-0000-4000-8000-000000000051','Spark 1','Spark 1 — Beginner A1','A1',true,'S1','Beginner A1') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, "isPublished"=true, "trackKey"=EXCLUDED."trackKey", "cefrTier"=EXCLUDED."cefrTier";
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('9c4fbec9-3bc4-55c1-a01d-6be798c86213','a0000000-0000-4000-8000-000000000051','Блок 1. A / An (Indefinite Article)',1,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('f3e8a26a-1d20-5560-9d9a-ac02a64bea8b','9c4fbec9-3bc4-55c1-a01d-6be798c86213','A / An (Indefinite Article)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'a' before a word that begins with a consonant sound (a cat, a book, a pen). We use 'an' before a word that begins with a vowel sound (an apple, an egg, an umbrella). We use a/an with singular countable nouns."}, {"type": "examples", "items": ["a dog", "a balloon", "an apple", "an egg", "an eagle", "an orange"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('af365465-ec03-5b2f-be3a-280979b7d0c5','f3e8a26a-1d20-5560-9d9a-ac02a64bea8b',0,'CHOOSE','Выберите правильный артикль: a или an.',$j${"items": [{"before": "This is", "after": "cat.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "This is", "after": "apple.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "It's", "after": "egg.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "I have got", "after": "pen.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "That's", "after": "eagle.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "It's", "after": "balloon.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "This is", "after": "orange.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "I can see", "after": "bird.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('af365465-ec03-5b2f-be3a-280979b7d0c5',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('adafeb30-5341-5e2f-9274-77a6e9b22702','f3e8a26a-1d20-5560-9d9a-ac02a64bea8b',1,'SORT_COLUMNS','Распределите слова по столбцам: с каким артиклем они употребляются — a или an.',$j${"columns": [{"id": "c1", "label": "a"}, {"id": "c2", "label": "an"}], "items": [{"id": "i1", "label": "cat"}, {"id": "i2", "label": "apple"}, {"id": "i3", "label": "book"}, {"id": "i4", "label": "egg"}, {"id": "i5", "label": "eagle"}, {"id": "i6", "label": "balloon"}, {"id": "i7", "label": "orange"}, {"id": "i8", "label": "pencil"}, {"id": "i9", "label": "umbrella"}, {"id": "i10", "label": "dog"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('adafeb30-5341-5e2f-9274-77a6e9b22702',$j${"placement": {"i1": "c1", "i2": "c2", "i3": "c1", "i4": "c2", "i5": "c2", "i6": "c1", "i7": "c2", "i8": "c1", "i9": "c2", "i10": "c1"}}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('28fc9624-3386-577b-b012-15b9527989d6','f3e8a26a-1d20-5560-9d9a-ac02a64bea8b',2,'FILL_BLANK','Впишите артикль a или an.',$j${"items": [{"before": "It's", "after": "elephant."}, {"before": "This is", "after": "chair."}, {"before": "That is", "after": "umbrella."}, {"before": "I have got", "after": "schoolbag."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('28fc9624-3386-577b-b012-15b9527989d6',$j${"items": [{"accept": ["an"]}, {"accept": ["a"]}, {"accept": ["an"]}, {"accept": ["a"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('655f6f9a-dfa5-533d-8df2-6acc78d36a5d','a0000000-0000-4000-8000-000000000051','Блок 2. The verb ''to be''',2,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('993023ca-ff62-5e57-a913-07d76a38f8a4','655f6f9a-dfa5-533d-8df2-6acc78d36a5d','The verb ''to be''',0,'LESSON',70,$j$[{"type": "rule", "text": "The verb 'to be' has three forms in the Present Simple: am, is, are. Affirmative: I am, you/we/they are, he/she/it is. Short forms: I'm, you're, he's, she's, it's, we're, they're."}, {"type": "rule", "text": "Negative: add 'not' (I am not / I'm not, he is not / isn't, they are not / aren't). Interrogative: put am/is/are before the subject (Are you a student?). Short answers: Yes, I am. / No, I'm not."}, {"type": "examples", "items": ["I am a student.", "She is happy.", "They are from Spain.", "Are you a teacher? Yes, I am.", "Is he your dad? No, he isn't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('24912c25-4234-593b-ac91-20b562ee164e','993023ca-ff62-5e57-a913-07d76a38f8a4',0,'FILL_BLANK','Впишите нужную форму глагола to be: am, is или are.',$j${"items": [{"before": "I", "after": "a student."}, {"before": "She", "after": "happy."}, {"before": "They", "after": "from Spain."}, {"before": "You", "after": "my friend."}, {"before": "He", "after": "a teacher."}, {"before": "It", "after": "a cat."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('24912c25-4234-593b-ac91-20b562ee164e',$j${"items": [{"accept": ["am"]}, {"accept": ["is"]}, {"accept": ["are"]}, {"accept": ["are"]}, {"accept": ["is"]}, {"accept": ["is"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f6fb8121-6973-5f81-8d33-53e443963d71','993023ca-ff62-5e57-a913-07d76a38f8a4',1,'CHOOSE','Выберите правильную короткую форму (отрицание или краткий ответ).',$j${"items": [{"before": "\"Are they students?\" \"No, they", "after": ".\"", "options": [{"id": "o1", "label": "aren't"}, {"id": "o2", "label": "isn't"}]}, {"before": "\"Are you from Canada?\" \"No, I", "after": ".\"", "options": [{"id": "o1", "label": "'m not"}, {"id": "o2", "label": "aren't"}]}, {"before": "\"Is she your sister?\" \"No, she", "after": ".\"", "options": [{"id": "o1", "label": "isn't"}, {"id": "o2", "label": "aren't"}]}, {"before": "\"Are you a teacher?\" \"Yes, I", "after": ".\"", "options": [{"id": "o1", "label": "am"}, {"id": "o2", "label": "is"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('f6fb8121-6973-5f81-8d33-53e443963d71',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('1cced2d4-0df9-5177-ae1d-dae5bd07d1c8','993023ca-ff62-5e57-a913-07d76a38f8a4',2,'REORDER','Составьте предложение из слов.',$j${"tiles": ["She", "is", "a", "teacher"]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('1cced2d4-0df9-5177-ae1d-dae5bd07d1c8',$j${"order": ["She", "is", "a", "teacher"]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('b42bcf01-3e0f-5def-bed3-6a29b1385657','a0000000-0000-4000-8000-000000000051','Блок 3. Personal Subject / Object Pronouns',3,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('154a6f20-6539-5162-9f4f-186a6801ee34','b42bcf01-3e0f-5def-bed3-6a29b1385657','Personal Subject / Object Pronouns',0,'LESSON',70,$j$[{"type": "rule", "text": "Subject pronouns (I, you, he, she, it, we, you, they) come before the verb and do the action. We use 'he' for a man/boy, 'she' for a woman/girl, 'it' for a thing or animal, 'they' for more than one."}, {"type": "rule", "text": "Object pronouns (me, you, him, her, it, us, you, them) come after the verb or after a preposition (Look at him. She loves us.)."}, {"type": "examples", "items": ["He is my friend.", "Look at her.", "They are happy.", "I can see them.", "Where is it?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a390034f-36a5-5a5d-b48b-5ad73ab0e782','154a6f20-6539-5162-9f4f-186a6801ee34',0,'MATCH_PAIRS','Соедините личное местоимение (подлежащее) с соответствующим объектным местоимением.',$j${"left": [{"id": "l1", "label": "I"}, {"id": "l2", "label": "he"}, {"id": "l3", "label": "she"}, {"id": "l4", "label": "we"}, {"id": "l5", "label": "they"}], "right": [{"id": "r1", "label": "me"}, {"id": "r2", "label": "him"}, {"id": "r3", "label": "her"}, {"id": "r4", "label": "us"}, {"id": "r5", "label": "them"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('a390034f-36a5-5a5d-b48b-5ad73ab0e782',$j${"pairs": [{"l": "l1", "r": "r1"}, {"l": "l2", "r": "r2"}, {"l": "l3", "r": "r3"}, {"l": "l4", "r": "r4"}, {"l": "l5", "r": "r5"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('91f767cf-1c19-5f0e-83c6-cc4b2818e58e','154a6f20-6539-5162-9f4f-186a6801ee34',1,'CHOOSE','Выберите правильное местоимение.',$j${"items": [{"before": "Sue and Bill are French.", "after": "are from France.", "options": [{"id": "o1", "label": "Them"}, {"id": "o2", "label": "They"}]}, {"before": "Look at Sarah and Sue. Look at", "after": ".", "options": [{"id": "o1", "label": "them"}, {"id": "o2", "label": "they"}]}, {"before": "Where is my bag? Where is", "after": "?", "options": [{"id": "o1", "label": "it"}, {"id": "o2", "label": "them"}]}, {"before": "I like my teachers. I love", "after": ".", "options": [{"id": "o1", "label": "they"}, {"id": "o2", "label": "them"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('91f767cf-1c19-5f0e-83c6-cc4b2818e58e',$j${"items": [{"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5fffca15-74a0-501d-b534-c04205206578','154a6f20-6539-5162-9f4f-186a6801ee34',2,'FILL_BLANK','Замените выделенное слово местоимением-подлежащим (he, she, it или they).',$j${"items": [{"before": "Tom is my friend.", "after": "is happy."}, {"before": "Mary is a nurse.", "after": "is nice."}, {"before": "The dog is big.", "after": "is black."}, {"before": "The boys are here.", "after": "are students."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('5fffca15-74a0-501d-b534-c04205206578',$j${"items": [{"accept": ["He"]}, {"accept": ["She"]}, {"accept": ["It"]}, {"accept": ["They"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('07ab185c-b5c3-5945-bd19-7faa92a2fa80','a0000000-0000-4000-8000-000000000051','Блок 4. The verb ''have got''',4,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('9d1f471d-538f-508e-be77-c53faffa0d70','07ab185c-b5c3-5945-bd19-7faa92a2fa80','The verb ''have got''',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'have got' to talk about possession. Use 'have got' ('ve got) with I/you/we/they and 'has got' ('s got) with he/she/it."}, {"type": "rule", "text": "Negative: haven't got / hasn't got. Interrogative: Have you got...? / Has he got...? Short answers: Yes, I have. / No, he hasn't."}, {"type": "examples", "items": ["I have got a dog.", "She has got a bike.", "They haven't got a car.", "Have you got a pen? Yes, I have.", "Has he got a guitar? No, he hasn't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('22ee2ab8-7350-577a-8e31-723b15cf2bab','9d1f471d-538f-508e-be77-c53faffa0d70',0,'CHOOSE','Выберите правильную форму: have или has.',$j${"items": [{"before": "She", "after": "got a bike.", "options": [{"id": "o1", "label": "has"}, {"id": "o2", "label": "have"}]}, {"before": "They", "after": "got a cat.", "options": [{"id": "o1", "label": "has"}, {"id": "o2", "label": "have"}]}, {"before": "He", "after": "got a guitar.", "options": [{"id": "o1", "label": "has"}, {"id": "o2", "label": "have"}]}, {"before": "I", "after": "got a schoolbag.", "options": [{"id": "o1", "label": "has"}, {"id": "o2", "label": "have"}]}, {"before": "It", "after": "got a long tail.", "options": [{"id": "o1", "label": "has"}, {"id": "o2", "label": "have"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('22ee2ab8-7350-577a-8e31-723b15cf2bab',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('84f30e3c-67ec-5b79-bb4a-b6da451a83b5','9d1f471d-538f-508e-be77-c53faffa0d70',1,'CHOOSE','Выберите правильную отрицательную форму.',$j${"items": [{"before": "He", "after": "got a bike.", "options": [{"id": "o1", "label": "hasn't"}, {"id": "o2", "label": "haven't"}]}, {"before": "They", "after": "got a dog.", "options": [{"id": "o1", "label": "hasn't"}, {"id": "o2", "label": "haven't"}]}]}$j$::jsonb,10);
