INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('52ba9cd7-2a50-5e27-86d3-797dda5eeb5d','a0000000-0000-4000-8000-000000000051','Блок 5. This / These - That / Those',5,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('540d0eae-cf58-5e3b-9495-ac0c43ed5280','52ba9cd7-2a50-5e27-86d3-797dda5eeb5d','This / These - That / Those',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'this' (singular) and 'these' (plural) for things that are near us. We use 'that' (singular) and 'those' (plural) for things that are far from us."}, {"type": "examples", "items": ["This is a book.", "These are books.", "That is a dog.", "Those are dogs."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('12438e69-8d8e-531e-bc29-79e93edf6cff','540d0eae-cf58-5e3b-9495-ac0c43ed5280',0,'CHOOSE','Выберите правильное указательное местоимение.',$j${"items": [{"before": "(here)", "after": "is a pen.", "options": [{"id": "o1", "label": "This"}, {"id": "o2", "label": "These"}]}, {"before": "(here)", "after": "are pens.", "options": [{"id": "o1", "label": "This"}, {"id": "o2", "label": "These"}]}, {"before": "(over there)", "after": "is a car.", "options": [{"id": "o1", "label": "That"}, {"id": "o2", "label": "Those"}]}, {"before": "(over there)", "after": "are cars.", "options": [{"id": "o1", "label": "That"}, {"id": "o2", "label": "Those"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('12438e69-8d8e-531e-bc29-79e93edf6cff',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('51cddbf7-dcbe-55a2-98b7-dd8e4b234f24','540d0eae-cf58-5e3b-9495-ac0c43ed5280',1,'FILL_BLANK','Впишите множественное указательное местоимение (These или Those).',$j${"items": [{"before": "This is a book.", "after": "are books."}, {"before": "That is a boy.", "after": "are boys."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('51cddbf7-dcbe-55a2-98b7-dd8e4b234f24',$j${"items": [{"accept": ["These"]}, {"accept": ["Those"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('545697ba-99e8-5721-ab17-bdc011f4daaa','540d0eae-cf58-5e3b-9495-ac0c43ed5280',2,'SORT_COLUMNS','Распределите местоимения по числу: единственное или множественное.',$j${"columns": [{"id": "c1", "label": "Singular"}, {"id": "c2", "label": "Plural"}], "items": [{"id": "i1", "label": "this"}, {"id": "i2", "label": "these"}, {"id": "i3", "label": "that"}, {"id": "i4", "label": "those"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('545697ba-99e8-5721-ab17-bdc011f4daaa',$j${"placement": {"i1": "c1", "i2": "c2", "i3": "c1", "i4": "c2"}}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('93b6db6b-d905-57e9-a3ca-f7698d2f264d','a0000000-0000-4000-8000-000000000051','Блок 6. Plurals',6,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('7c51c422-74f5-5602-b94f-3d0387ce71fd','93b6db6b-d905-57e9-a3ca-f7698d2f264d','Plurals',0,'LESSON',70,$j$[{"type": "rule", "text": "Most nouns form the plural by adding -s (cat > cats). Nouns ending in -s, -ss, -sh, -ch, -x add -es (bus > buses, box > boxes). Nouns ending in a consonant + y change y to -ies (baby > babies). Nouns ending in -f/-fe change to -ves (leaf > leaves, knife > knives)."}, {"type": "rule", "text": "Some nouns have irregular plurals: man > men, woman > women, child > children, foot > feet, tooth > teeth, mouse > mice."}, {"type": "examples", "items": ["book > books", "watch > watches", "party > parties", "wolf > wolves", "man > men"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e64e3aec-1bf0-5e9f-83df-b2e20c496e0a','7c51c422-74f5-5602-b94f-3d0387ce71fd',0,'SORT_COLUMNS','Распределите слова во множественном числе по способу образования.',$j${"columns": [{"id": "c1", "label": "-s"}, {"id": "c2", "label": "-es"}, {"id": "c3", "label": "-ies"}, {"id": "c4", "label": "-ves"}, {"id": "c5", "label": "irregular"}], "items": [{"id": "i1", "label": "books"}, {"id": "i2", "label": "glasses"}, {"id": "i3", "label": "cities"}, {"id": "i4", "label": "wolves"}, {"id": "i5", "label": "men"}, {"id": "i6", "label": "boxes"}, {"id": "i7", "label": "babies"}, {"id": "i8", "label": "dogs"}]}$j$::jsonb,10);
