INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('56b8906a-7b54-5baf-a1ca-20f016a7f484','a0000000-0000-4000-8000-000000000051','Блок 7. Possessives (Possessive Adjectives & Possessive ''s)',7,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('f22467c8-6b28-5cba-8d12-be0803d8ce1d','56b8906a-7b54-5baf-a1ca-20f016a7f484','Possessives (Possessive Adjectives & Possessive ''s)',0,'LESSON',70,$j$[{"type": "rule", "text": "Possessive adjectives (my, your, his, her, its, our, their) go before a noun to show who something belongs to: my book, her bag, their toys."}, {"type": "rule", "text": "We add 's to a person's name or a singular noun to show possession: Tim's guitar, the dog's tail. With plural nouns ending in -s we add only an apostrophe: the girls' room."}, {"type": "examples", "items": ["This is my book.", "That is her bag.", "This is Tim's guitar.", "The boys' ball is here."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('79d60105-bd83-5e44-a9de-608f870058e1','f22467c8-6b28-5cba-8d12-be0803d8ce1d',0,'CHOOSE','Выберите правильное притяжательное прилагательное.',$j${"items": [{"before": "This is", "after": "book. (I)", "options": [{"id": "o1", "label": "my"}, {"id": "o2", "label": "me"}]}, {"before": "That is", "after": "dog. (he)", "options": [{"id": "o1", "label": "his"}, {"id": "o2", "label": "him"}]}, {"before": "Sarah has got a cat.", "after": "cat is black. (she)", "options": [{"id": "o1", "label": "her"}, {"id": "o2", "label": "she"}]}, {"before": "We love", "after": "school. (we)", "options": [{"id": "o1", "label": "our"}, {"id": "o2", "label": "us"}]}, {"before": "They have got", "after": "toys. (they)", "options": [{"id": "o1", "label": "their"}, {"id": "o2", "label": "them"}]}]}$j$::jsonb,10);
