INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('715e9e7f-daca-551b-a1a7-548c6c77d928','f22467c8-6b28-5cba-8d12-be0803d8ce1d',1,'MATCH_PAIRS','Соедините личное местоимение с притяжательным прилагательным.',$j${"left": [{"id": "l1", "label": "I"}, {"id": "l2", "label": "you"}, {"id": "l3", "label": "he"}, {"id": "l4", "label": "she"}, {"id": "l5", "label": "we"}, {"id": "l6", "label": "they"}], "right": [{"id": "r1", "label": "my"}, {"id": "r2", "label": "your"}, {"id": "r3", "label": "his"}, {"id": "r4", "label": "her"}, {"id": "r5", "label": "our"}, {"id": "r6", "label": "their"}]}$j$::jsonb,10);
