INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('58b07ec4-e2a2-507f-b6c3-367052676e03','f22467c8-6b28-5cba-8d12-be0803d8ce1d',2,'FILL_BLANK','Впишите ''s, чтобы показать принадлежность.',$j${"items": [{"before": "This is Tim. This is Tim", "after": "guitar."}, {"before": "This is Anna. This is Anna", "after": "bag."}, {"before": "This is the dog. This is the dog", "after": "ball."}]}$j$::jsonb,10);
