INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('3d481d3f-8074-5da9-b0cf-31f0883fac4b','a0000000-0000-4000-8000-000000000051','Блок 8. Can',8,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('dce40812-aebb-51bd-a6de-69d848f8a532','3d481d3f-8074-5da9-b0cf-31f0883fac4b','Can',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'can' to talk about ability (what someone is able to do). 'Can' is the same for all persons (I/you/he/she/it/we/they can). The main verb after 'can' is in the base form (I can swim)."}, {"type": "rule", "text": "Negative: can't (cannot). Interrogative: Can + subject + verb? (Can you swim?). Short answers: Yes, I can. / No, I can't."}, {"type": "examples", "items": ["I can swim.", "She can play the guitar.", "He can't dance.", "Can you sing? Yes, I can."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c8326af5-23a0-5938-bf16-2e43142c2c20','dce40812-aebb-51bd-a6de-69d848f8a532',0,'CHOOSE','Выберите can или can''t в соответствии со знаком (✓ = может, ✗ = не может).',$j${"items": [{"before": "She", "after": "swim. (✓)", "options": [{"id": "o1", "label": "can"}, {"id": "o2", "label": "can't"}]}, {"before": "He", "after": "ski. (✗)", "options": [{"id": "o1", "label": "can"}, {"id": "o2", "label": "can't"}]}, {"before": "They", "after": "play the guitar. (✓)", "options": [{"id": "o1", "label": "can"}, {"id": "o2", "label": "can't"}]}, {"before": "I", "after": "dance. (✗)", "options": [{"id": "o1", "label": "can"}, {"id": "o2", "label": "can't"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('c8326af5-23a0-5938-bf16-2e43142c2c20',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
