INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('1e4691fd-7220-5e5a-8f3c-7a34c938a589','a0000000-0000-4000-8000-000000000051','Блок 9. There is/There are',9,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('8cdc9bbb-1e41-58f4-9fa1-2bd7f9e93c84','1e4691fd-7220-5e5a-8f3c-7a34c938a589','There is/There are',0,'LESSON',70,$j$[{"type": "rule", "text": "We use There is (There's) with singular nouns and There are with plural nouns."}, {"type": "rule", "text": "Negative: There isn't (is not) a... / There aren't (are not) any..."}, {"type": "rule", "text": "Questions: Is there...? / Are there...? Short answers: Yes, there is. / No, there isn't. Yes, there are. / No, there aren't."}, {"type": "examples", "items": ["There is a bed in the room.", "There are two windows in the bedroom.", "Is there a lamp on the desk?", "Are there any books on the shelf?"]}]$j$::jsonb);
