INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('966eee8a-4a01-5d17-94ec-2c06dc18f842','8cdc9bbb-1e41-58f4-9fa1-2bd7f9e93c84',1,'FILL_BLANK','Вставьте isn''t или aren''t.',$j${"items": [{"before": "There", "after": "a TV in the bedroom."}, {"before": "There", "after": "any chairs in the kitchen."}, {"before": "There", "after": "a dog in the garden."}, {"before": "There", "after": "any books on the shelf."}, {"before": "There", "after": "a lamp on the desk."}]}$j$::jsonb,10);
