INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('06058b1f-12f4-5d4e-9375-bb0dbf0f1160','a0000000-0000-4000-8000-000000000051','Блок 10. A/An – Some/Any – The',10,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('d7affb0f-5a87-5e01-9e4f-fc5b838bfaa2','06058b1f-12f4-5d4e-9375-bb0dbf0f1160','A/An – Some/Any – The',0,'LESSON',70,$j$[{"type": "rule", "text": "We use a/an with singular countable nouns. We use a before consonant sounds and an before vowel sounds."}, {"type": "rule", "text": "We use some in affirmative sentences and any in questions and negatives, with plural and uncountable nouns."}, {"type": "rule", "text": "We use the when we talk about something specific or something already mentioned."}, {"type": "examples", "items": ["a book, an apple, an hour", "There are some pencils on the desk.", "There isn't any milk. Is there any juice?", "The sun is very hot today."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('479ce4bd-25e4-58f4-b8b1-c794b2e0e877','d7affb0f-5a87-5e01-9e4f-fc5b838bfaa2',0,'FILL_BLANK','Вставьте some или any.',$j${"items": [{"before": "She hasn't got", "after": "gloves."}, {"before": "Would you like", "after": "biscuits?"}, {"before": "He has", "after": "posters of footballers in his bedroom."}, {"before": "There are", "after": "pencils on my desk."}, {"before": "There aren't", "after": "slippers under the bed."}, {"before": "We have got", "after": "new students in our class."}, {"before": "There isn't", "after": "pizza!"}, {"before": "Are there", "after": "spiders in the bathroom?"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('479ce4bd-25e4-58f4-b8b1-c794b2e0e877',$j${"items": [{"accept": ["any"]}, {"accept": ["some"]}, {"accept": ["some"]}, {"accept": ["some"]}, {"accept": ["any"]}, {"accept": ["some"]}, {"accept": ["any"]}, {"accept": ["any"]}]}$j$::jsonb,'');
