INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('959aefcf-e56f-5ed7-a69e-5d7e026c5aa9','a0000000-0000-4000-8000-000000000051','Блок 12. The imperative',12,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('cdf383cd-8ac4-5168-a2d9-2fb1bb313ff3','959aefcf-e56f-5ed7-a69e-5d7e026c5aa9','The imperative',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the imperative with the base form of the verb: Open the door. Sit down."}, {"type": "rule", "text": "The negative imperative is Don't + verb: Don't run! Don't be late!"}, {"type": "rule", "text": "We use Let's + verb to make suggestions: Let's go to the cinema."}, {"type": "examples", "items": ["Close the window.", "Don't shout in class.", "Let's play football."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ed6c52ce-c3f3-5362-a673-5284ea05b1a6','cdf383cd-8ac4-5168-a2d9-2fb1bb313ff3',0,'FILL_BLANK','Перепишите предложения в отрицательной форме, добавив Don''t.',$j${"items": [{"before": "", "after": "give Claire the ball!"}, {"before": "", "after": "put on a jacket!"}, {"before": "", "after": "help him with his homework."}, {"before": "", "after": "turn off the TV!"}, {"before": "", "after": "close the door, please."}, {"before": "", "after": "show me your new dress."}, {"before": "", "after": "close your books, please."}, {"before": "", "after": "put your notebook in your bag."}]}$j$::jsonb,10);
