INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c0d0031c-19f6-57f7-847a-4b94dc184a87','cdf383cd-8ac4-5168-a2d9-2fb1bb313ff3',5,'FILL_BLANK','Дополните предложения при помощи Let''s и глагола в скобках.',$j${"items": [{"before": "OK,", "after": "home then. (go)"}, {"before": "Me too.", "after": "some sandwiches. (make)"}, {"before": "Yes, it is.", "after": "for a walk. (go)"}, {"before": "Oh dear!", "after": "him to the doctor. (take)"}, {"before": "Yes, they are.", "after": "your Dad for help. (ask)"}, {"before": "Great!", "after": "it. (watch)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('c0d0031c-19f6-57f7-847a-4b94dc184a87',$j${"items": [{"accept": ["Let's go", "Lets go", "let's go"]}, {"accept": ["Let's make", "Lets make", "let's make"]}, {"accept": ["Let's go", "Lets go", "let's go"]}, {"accept": ["Let's take", "Lets take", "let's take"]}, {"accept": ["Let's ask", "Lets ask", "let's ask"]}, {"accept": ["Let's watch", "Lets watch", "let's watch"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6aec8cca-4020-5c3e-9cb8-a0c057e27bcb','cdf383cd-8ac4-5168-a2d9-2fb1bb313ff3',6,'FILL_BLANK','Вставьте правильную форму глагола в скобках (Don''t, Let''s или только глагол).',$j${"items": [{"before": "It's dark in here.", "after": "the light, please. (turn on)"}, {"before": "The baby is asleep.", "after": "noise! (make)"}, {"before": "It's cold in here.", "after": "the window! (open)"}, {"before": "I'm bored.", "after": "a game. (play)"}, {"before": "", "after": "some cake! It's delicious! (have)"}, {"before": "", "after": "TV now! You've got a lot of homework. (watch)"}, {"before": "It's 8 o'clock.", "after": "children! (wake up)"}, {"before": "It's Tina's birthday next week.", "after": "a surprise party for her. (have)"}]}$j$::jsonb,10);
