INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('96d61f50-f8e1-50af-bfe9-464ff20806f3','a0000000-0000-4000-8000-000000000051','Блок 13. The possessive case',13,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('d793d3d5-34d2-5504-9c3a-2c0630582083','96d61f50-f8e1-50af-bfe9-464ff20806f3','The possessive case',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 's with singular nouns and irregular plurals to show possession: Tom's bike, the children's room."}, {"type": "rule", "text": "We use only an apostrophe (') with regular plural nouns that end in -s: the girls' books, my parents' car."}, {"type": "examples", "items": ["This is Sara's pen.", "The dog's bone is under the table.", "The boys' team won the match.", "The men's shoes are new."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0ca2ca5a-5cb9-56b7-ae87-75d3a752938a','d793d3d5-34d2-5504-9c3a-2c0630582083',0,'CHOOSE','Выберите правильный вариант притяжательного падежа.',$j${"items": [{"before": "the boy", "after": "ball (one boy)", "options": [{"id": "o1", "label": "'s"}, {"id": "o2", "label": "'"}]}, {"before": "the boys", "after": "ball (two boys)", "options": [{"id": "o1", "label": "'s"}, {"id": "o2", "label": "'"}]}, {"before": "the children", "after": "books", "options": [{"id": "o1", "label": "'s"}, {"id": "o2", "label": "'"}]}, {"before": "my sisters", "after": "room (two sisters)", "options": [{"id": "o1", "label": "'s"}, {"id": "o2", "label": "'"}]}, {"before": "the man", "after": "hat", "options": [{"id": "o1", "label": "'s"}, {"id": "o2", "label": "'"}]}, {"before": "the students", "after": "desks", "options": [{"id": "o1", "label": "'s"}, {"id": "o2", "label": "'"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('0ca2ca5a-5cb9-56b7-ae87-75d3a752938a',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('bb1996fd-e315-51a3-a90a-9eb5f88775c2','d793d3d5-34d2-5504-9c3a-2c0630582083',1,'FILL_BLANK','Образуйте притяжательный падеж от слова в скобках.',$j${"items": [{"before": "This is", "after": "dog. (Anna)"}, {"before": "The", "after": "toys are new. (children)"}, {"before": "My", "after": "house is big. (parents)"}, {"before": "The", "after": "tail is long. (dog)"}, {"before": "Those are the", "after": "bikes. (girls)"}]}$j$::jsonb,10);
