INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('21b108dc-27b7-501f-ab13-976b238add7b','a0000000-0000-4000-8000-000000000051','Блок 14. Present Simple',14,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('4ce9a0ed-b662-518d-ab4d-d919f79d6be5','21b108dc-27b7-501f-ab13-976b238add7b','Present Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present simple for habits, routines, timetables and permanent situations, often with adverbs of frequency (always, usually, often, sometimes, never)."}, {"type": "rule", "text": "Affirmative: I / you / we / they + base verb; he / she / it + verb + -s / -es (he works, she watches)."}, {"type": "rule", "text": "Negative: I / you / we / they + don't + base verb; he / she / it + doesn't + base verb."}, {"type": "rule", "text": "Interrogative: Do I / you / we / they + base verb? Does he / she / it + base verb? Short answers: Yes, he does. / No, he doesn't."}, {"type": "examples", "items": ["She cooks dinner every evening.", "He doesn't watch TV in the morning.", "Does he go to the gym every day?", "What time does she have breakfast?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('50b54090-2d6f-5fb8-9b4f-7bb2a4e2c7df','4ce9a0ed-b662-518d-ab4d-d919f79d6be5',0,'FILL_BLANK','Поставьте глагол в скобках в правильную форму Present Simple.',$j${"items": [{"before": "I", "after": "(play) tennis on Mondays."}, {"before": "My best friend", "after": "(walk) to school in the morning."}, {"before": "My granddad", "after": "(like) basketball."}, {"before": "We", "after": "(live) in a big house with a garden."}, {"before": "I", "after": "(help) around the house."}, {"before": "My brother", "after": "(get up) early every day to go to the gym."}, {"before": "I", "after": "(do) my homework every day."}, {"before": "My friends", "after": "(play) baseball."}, {"before": "My mum", "after": "(work) at the weekend."}, {"before": "My family and I", "after": "(have) dinner at 8 o'clock every evening."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('50b54090-2d6f-5fb8-9b4f-7bb2a4e2c7df',$j${"items": [{"accept": ["play"]}, {"accept": ["walks"]}, {"accept": ["likes"]}, {"accept": ["live"]}, {"accept": ["help"]}, {"accept": ["gets up"]}, {"accept": ["do"]}, {"accept": ["play"]}, {"accept": ["works"]}, {"accept": ["have"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f064660b-0742-507c-88d6-42332d1a6362','4ce9a0ed-b662-518d-ab4d-d919f79d6be5',1,'MATCH_PAIRS','Соотнесите вопросы с ответами.',$j${"left": [{"id": "l1", "label": "What does he do?"}, {"id": "l2", "label": "What time does she have breakfast?"}, {"id": "l3", "label": "How does he go to work?"}, {"id": "l4", "label": "Does he go to the gym every day?"}, {"id": "l5", "label": "When does he play football?"}, {"id": "l6", "label": "What does he do in the evening?"}], "right": [{"id": "r1", "label": "He plays football at the weekend."}, {"id": "r2", "label": "No, he doesn't."}, {"id": "r3", "label": "She has breakfast at 8 o'clock."}, {"id": "r4", "label": "He is a vet."}, {"id": "r5", "label": "He watches TV in the evening."}, {"id": "r6", "label": "He rides his bike to work."}]}$j$::jsonb,10);
