INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('6e8669f2-af29-576a-9ca4-5ab1267db622','0fec31a6-2e18-5d8b-b723-b18cbdc1e1d8','Like, love, hate + -ing form',0,'LESSON',70,$j$[{"type": "rule", "text": "After the verbs like, love, enjoy and hate we usually use the -ing form of the verb (the gerund)."}, {"type": "rule", "text": "Spelling of the -ing form: add -ing to most verbs (play → playing); for verbs ending in -e, drop the -e (make → making); for short verbs ending in consonant-vowel-consonant, double the last consonant (swim → swimming)."}, {"type": "examples", "items": ["He likes playing football.", "She loves listening to music.", "He hates losing a race.", "I enjoy reading books."]}]$j$::jsonb);
