}]}, {"before": "Are", "after": "your gloves on the table?", "options": [{"id": "o1", "label": "this"}, {"id": "o2", "label": "those"}, {"id": "o3", "label": "that"}]}, {"before": "There are some", "after": "on the ground.", "options": [{"id": "o1", "label": "leafs"}, {"id": "o2", "label": "leafes"}, {"id": "o3", "label": "leaves"}]}, {"before": "", "after": "shop next to the bakery sells shoes.", "options": [{"id": "o1", "label": "An"}, {"id": "o2", "label": "The"}, {"id": "o3", "label": "A"}]}, {"before": "\"Can you play tennis?\"", "after": "", "options": [{"id": "o1", "label": "No, I can't"}, {"id": "o2", "label": "No, I can"}, {"id": "o3", "label": "No, I can not"}]}, {"before": "", "after": "any bathrooms upstairs.", "options": [{"id": "o1", "label": "There isn't"}, {"id": "o2", "label": "There aren't"}, {"id": "o3", "label": "Isn't there"}]}, {"before": "\"Who's Paul?\" \"He's", "after": "uncle.\"", "options": [{"id": "o1", "label": "Ryan's"}, {"id": "o2", "label": "Ryans"}, {"id": "o3", "label": "Ryans'"}]}, {"before": "He", "after": "doing the housework.", "options": [{"id": "o1", "label": "doesn't like"}, {"id": "o2", "label": "doesn't likes"}, {"id": "o3", "label": "like"}]}, {"before": "\"", "after": "handbag is this?\" \"Sue's.\"", "options": [{"id": "o1", "label": "Who's"}, {"id": "o2", "label": "Which"}, {"id": "o3", "label": "Whose"}]}, {"before": "", "after": "got a car?", "options": [{"id": "o1", "label": "He has not"}, {"id": "o2", "label": "He has"}, {"id": "o3", "label": "Has he"}]}]}$j$::jsonb,10);
