INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('aa45bc41-27ef-5d10-8d28-6c6897550efb','a0000000-0000-4000-8000-000000000051','Блок 16. Adverbs of frequency',16,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('a9c80041-c022-5e85-865c-311a9b68a975','aa45bc41-27ef-5d10-8d28-6c6897550efb','Adverbs of frequency',0,'LESSON',70,$j$[{"type": "rule", "text": "Adverbs of frequency (always, usually, often, sometimes, rarely, never) tell us how often we do something."}, {"type": "rule", "text": "They go before the main verb but after the verb 'to be': I always get up early. / She is never late."}, {"type": "examples", "items": ["I always brush my teeth.", "He usually walks to school.", "They often play football.", "We never eat fast food."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b741f27e-76f9-546b-ac63-0fc533c842f1','a9c80041-c022-5e85-865c-311a9b68a975',0,'CHOOSE','Выберите вариант с правильным порядком слов.',$j${"items": [{"before": "", "after": "", "options": [{"id": "o1", "label": "She is never late."}, {"id": "o2", "label": "She never is late."}]}, {"before": "", "after": "", "options": [{"id": "o1", "label": "I always get up early."}, {"id": "o2", "label": "I get up always early."}]}, {"before": "", "after": "", "options": [{"id": "o1", "label": "They often play football."}, {"id": "o2", "label": "They play often football."}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('b741f27e-76f9-546b-ac63-0fc533c842f1',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
