INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('661b403b-0cdd-50ff-9ae6-3de6039c18fb','a0000000-0000-4000-8000-000000000051','Блок 17. Prepositions of time',17,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('20be2516-9b70-519f-96ee-22fad33f9ec9','661b403b-0cdd-50ff-9ae6-3de6039c18fb','Prepositions of time',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'at' with clock times, festivals and the expressions at night and at the weekend: at 8 o'clock, at Christmas, at night."}, {"type": "rule", "text": "We use 'on' with days of the week and dates: on Monday, on 5th May, on my birthday."}, {"type": "rule", "text": "We use 'in' with months, seasons, years and parts of the day: in July, in summer, in 2010, in the morning."}, {"type": "examples", "items": ["at 7 o'clock", "on Sunday", "in the afternoon", "in December"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('cb4dd983-3801-504a-8afe-cc8673aebe8f','20be2516-9b70-519f-96ee-22fad33f9ec9',0,'FILL_BLANK','Вставьте at, on или in.',$j${"items": [{"before": "We meet", "after": "7 o'clock."}, {"before": "My birthday is", "after": "June."}, {"before": "I have a lesson", "after": "Monday."}, {"before": "It snows", "after": "winter."}, {"before": "See you", "after": "the weekend."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('cb4dd983-3801-504a-8afe-cc8673aebe8f',$j${"items": [{"accept": ["at"]}, {"accept": ["in"]}, {"accept": ["on"]}, {"accept": ["in"]}, {"accept": ["at"]}]}$j$::jsonb,'');
