INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('ea70b846-7147-5e17-9713-032f67044d49','a0000000-0000-4000-8000-000000000051','Блок 18. Comparatives – Superlatives',18,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c295696b-32ce-586a-94e0-b77351b1df79','ea70b846-7147-5e17-9713-032f67044d49','Comparatives – Superlatives',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the comparative to compare two people or things, and the superlative to compare one person or thing with a whole group."}, {"type": "rule", "text": "Short adjectives: add -er / -est (tall → taller → the tallest). Short adjectives ending in consonant-vowel-consonant double the last consonant (big → bigger → the biggest)."}, {"type": "rule", "text": "Adjectives ending in -y: change the y to i and add -er / -est (happy → happier → the happiest)."}, {"type": "rule", "text": "Longer adjectives: use more / most (expensive → more expensive → the most expensive)."}, {"type": "rule", "text": "Irregular forms: good → better → the best; bad → worse → the worst."}, {"type": "examples", "items": ["A dog is bigger than a cat.", "This is the tallest building.", "She is more beautiful than her sister.", "He is the best student."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2a371095-667d-5991-a263-4c36be273f7f','c295696b-32ce-586a-94e0-b77351b1df79',0,'FILL_BLANK','Раскройте скобки, употребив сравнительную или превосходную степень прилагательного.',$j${"items": [{"before": "A cat is", "after": "(small) than a dog."}, {"before": "Everest is", "after": "(high) mountain in the world."}, {"before": "This car is", "after": "(expensive) than that one."}, {"before": "He is", "after": "(good) player in the team."}, {"before": "Today is", "after": "(hot) than yesterday."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('2a371095-667d-5991-a263-4c36be273f7f',$j${"items": [{"accept": ["smaller"]}, {"accept": ["the highest"]}, {"accept": ["more expensive"]}, {"accept": ["the best"]}, {"accept": ["hotter"]}]}$j$::jsonb,'');
