INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('fa4b9c60-34a9-5acf-9c9e-9c4661e2d1c9','a0000000-0000-4000-8000-000000000051','Блок 19. Adverbs of degree',19,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('5fc9d837-c9e4-5eb1-93a0-c96470b3fb34','fa4b9c60-34a9-5acf-9c9e-9c4661e2d1c9','Adverbs of degree',0,'LESSON',70,$j$[{"type": "rule", "text": "Adverbs of degree (very, really, quite, too, a bit) go before an adjective or another adverb to make it stronger or weaker."}, {"type": "rule", "text": "'very' and 'really' make an adjective stronger; 'quite' and 'a bit' make it weaker; 'too' means 'more than necessary' and has a negative meaning."}, {"type": "examples", "items": ["The elephant is very big.", "This coffee is too hot.", "She is really tall.", "It is quite cold today."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5d0e41c2-08a8-5114-8310-2b7501a3f5b0','5fc9d837-c9e4-5eb1-93a0-c96470b3fb34',0,'CHOOSE','Выберите правильное наречие.',$j${"items": [{"before": "The coffee is", "after": "hot. I can't drink it.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "a bit"}]}, {"before": "The elephant is", "after": "big.", "options": [{"id": "o1", "label": "really"}, {"id": "o2", "label": "too"}]}, {"before": "It's", "after": "cold today, but not very cold.", "options": [{"id": "o1", "label": "a bit"}, {"id": "o2", "label": "too"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('5d0e41c2-08a8-5114-8310-2b7501a3f5b0',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
