INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('1119c012-ba31-5fe4-8613-180844deac4c','a0000000-0000-4000-8000-000000000051','Блок 20. Question words',20,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('57d68a12-e45b-5125-ab08-4a58ae6a49f5','1119c012-ba31-5fe4-8613-180844deac4c','Question words',0,'LESSON',70,$j$[{"type": "rule", "text": "We use question words to ask for specific information: what (things), who (people), where (place), when (time), why (reason), how (manner), whose (possession), which (choice), how often (frequency), how many (with countable nouns) and how much (with uncountable nouns/price)."}, {"type": "examples", "items": ["What is your name?", "Where do you live?", "How often do you play tennis?", "Whose bag is this?", "How much water do you drink?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ea6d4f7c-1ead-522c-912a-9671f8d8e1fb','57d68a12-e45b-5125-ab08-4a58ae6a49f5',0,'CHOOSE','Выберите правильное вопросительное слово.',$j${"items": [{"before": "", "after": "is your birthday? – In May.", "options": [{"id": "o1", "label": "When"}, {"id": "o2", "label": "Where"}, {"id": "o3", "label": "Who"}]}, {"before": "", "after": "do you go to school? – By bus.", "options": [{"id": "o1", "label": "Why"}, {"id": "o2", "label": "How"}, {"id": "o3", "label": "What"}]}, {"before": "", "after": "books are these? – They are mine.", "options": [{"id": "o1", "label": "Who"}, {"id": "o2", "label": "Whose"}, {"id": "o3", "label": "Which"}]}, {"before": "", "after": "are you sad? – Because I lost my dog.", "options": [{"id": "o1", "label": "When"}, {"id": "o2", "label": "Why"}, {"id": "o3", "label": "Where"}]}, {"before": "", "after": "pencils have you got? – Ten.", "options": [{"id": "o1", "label": "How much"}, {"id": "o2", "label": "How many"}, {"id": "o3", "label": "How often"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('ea6d4f7c-1ead-522c-912a-9671f8d8e1fb',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8e568a17-be31-5ddc-baed-dd71b455c2d6','57d68a12-e45b-5125-ab08-4a58ae6a49f5',1,'MATCH_PAIRS','Соедините вопрос с подходящим ответом.',$j${"left": [{"id": "l1", "label": "Where do you live?"}, {"id": "l2", "label": "When does the film start?"}, {"id": "l3", "label": "Who is your best friend?"}, {"id": "l4", "label": "How much is the ticket?"}], "right": [{"id": "r1", "label": "Five dollars."}, {"id": "r2", "label": "In London."}, {"id": "r3", "label": "At 7 o'clock."}, {"id": "r4", "label": "My brother Tom."}]}$j$::jsonb,10);
