INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c11ccffc-c1a2-5c0e-80d2-7fa4c16dc7b3','57d68a12-e45b-5125-ab08-4a58ae6a49f5',2,'FILL_BLANK','Впишите подходящее вопросительное слово.',$j${"items": [{"before": "", "after": "is your teacher? – Mrs Brown."}, {"before": "", "after": "do you live? – In Astana."}, {"before": "", "after": "old are you? – I'm twelve."}, {"before": "", "after": "colour is your car? – It's red."}]}$j$::jsonb,10);
