INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('c22b5c2c-154d-568c-ae51-c3de027a3ce4','a0000000-0000-4000-8000-000000000051','Блок 21. Present Continuous',21,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('d692dab5-b92c-593d-841a-ddf6598d5247','c22b5c2c-154d-568c-ae51-c3de027a3ce4','Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "The present continuous (am/is/are + verb-ing) describes actions happening now, at the moment of speaking. Affirmative: I am / he, she, it is / you, we, they are + -ing. Negative: add not (I'm not playing). Interrogative: put am/is/are before the subject (Is she reading?)."}, {"type": "rule", "text": "Spelling of the -ing form: most verbs just add -ing (play → playing); verbs ending in -e drop the -e and add -ing (make → making); verbs ending in one vowel + one consonant double the consonant and add -ing (sit → sitting, run → running)."}, {"type": "examples", "items": ["She is reading a book now.", "They are playing football at the moment.", "I am not sleeping.", "Is he swimming? – Yes, he is."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('89d9e61a-7ce8-555b-9e78-ac751d6f7994','d692dab5-b92c-593d-841a-ddf6598d5247',0,'SORT_COLUMNS','Распределите глаголы по способу образования формы -ing.',$j${"columns": [{"id": "c1", "label": "+ -ing"}, {"id": "c2", "label": "drop -e + -ing"}, {"id": "c3", "label": "double consonant + -ing"}], "items": [{"id": "i1", "label": "play"}, {"id": "i2", "label": "watch"}, {"id": "i3", "label": "make"}, {"id": "i4", "label": "write"}, {"id": "i5", "label": "ride"}, {"id": "i6", "label": "run"}, {"id": "i7", "label": "sit"}, {"id": "i8", "label": "swim"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('89d9e61a-7ce8-555b-9e78-ac751d6f7994',$j${"placement": {"i1": "c1", "i2": "c1", "i3": "c2", "i4": "c2", "i5": "c2", "i6": "c3", "i7": "c3", "i8": "c3"}}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('bcaee3c8-3486-5f5a-81db-fce50ff05bd5','d692dab5-b92c-593d-841a-ddf6598d5247',1,'FILL_BLANK','Поставьте глагол в скобках в present continuous.',$j${"items": [{"before": "Look! The baby", "after": "now. (sleep)"}, {"before": "They", "after": "tennis at the moment. (play)"}, {"before": "I", "after": "a letter now. (write)"}, {"before": "He", "after": "his bike in the park. (ride)"}, {"before": "The dogs", "after": "in the garden. (run)"}]}$j$::jsonb,10);
