INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('02a3a1e7-9360-5d80-b2ad-4a9c0a57e284','a0000000-0000-4000-8000-000000000051','Блок 22. Present Simple vs Present Continuous',22,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('5fbafbcf-4051-524a-ae18-3c6c4a07d2f8','02a3a1e7-9360-5d80-b2ad-4a9c0a57e284','Present Simple vs Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present simple for habits, routines, permanent states and facts. It is often used with adverbs such as always, usually, often, every day, on Saturdays. We use the present continuous for actions happening now or around the moment of speaking, and for fixed arrangements in the near future."}, {"type": "examples", "items": ["I get up at 7 o'clock every day.", "Look! It is snowing now.", "She usually walks to school.", "They are having dinner in a restaurant tonight."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d678208e-f7d4-58bc-8c69-8dff8048c67d','5fbafbcf-4051-524a-ae18-3c6c4a07d2f8',0,'FILL_BLANK','Поставьте глагол в present simple или present continuous.',$j${"items": [{"before": "A: Why", "after": "in here? (you/sit)"}, {"before": "B: Because it", "after": "outside. (snow)"}, {"before": "A: How often", "after": "your friends? (you/meet)"}, {"before": "B: I", "after": "them every weekend. (meet)"}, {"before": "A: What", "after": "on Saturdays? (you/do)"}, {"before": "B: I always", "after": "football. (play)"}, {"before": "B: They", "after": "in the school library. (study)"}, {"before": "A:", "after": "to come over for dinner tomorrow night? (you/want)"}, {"before": "B: I'm sorry but I can't. I", "after": "my grandparents tomorrow. (visit)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('d678208e-f7d4-58bc-8c69-8dff8048c67d',$j${"items": [{"accept": ["are you sitting"]}, {"accept": ["is snowing"]}, {"accept": ["do you meet"]}, {"accept": ["meet"]}, {"accept": ["do you do"]}, {"accept": ["play"]}, {"accept": ["are studying"]}, {"accept": ["Do you want"]}, {"accept": ["am visiting", "'m visiting"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c14168f9-09a3-5d9f-aaf3-5a3a9964b6dd','5fbafbcf-4051-524a-ae18-3c6c4a07d2f8',1,'CHOOSE','Выберите present simple или present continuous.',$j${"items": [{"before": "Sam", "after": "football every Sunday.", "options": [{"id": "o1", "label": "plays"}, {"id": "o2", "label": "is playing"}]}, {"before": "Listen! The birds", "after": ".", "options": [{"id": "o1", "label": "sing"}, {"id": "o2", "label": "are singing"}]}, {"before": "Water", "after": "at 100 degrees.", "options": [{"id": "o1", "label": "boils"}, {"id": "o2", "label": "is boiling"}]}, {"before": "I can't talk now, I", "after": "dinner.", "options": [{"id": "o1", "label": "cook"}, {"id": "o2", "label": "am cooking"}]}]}$j$::jsonb,10);
