INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('51250172-3567-5c23-93c8-d37599cdacc4','a0000000-0000-4000-8000-000000000051','Блок 23. Plurals',23,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('650870b8-2789-56cb-b1f6-0e2f16f40171','51250172-3567-5c23-93c8-d37599cdacc4','Plurals',0,'LESSON',70,$j$[{"type": "rule", "text": "Most nouns form the plural by adding -s (book → books). Nouns ending in -s, -ss, -sh, -ch or -x add -es (box → boxes, watch → watches). Nouns ending in a consonant + y change the y to -ies (baby → babies). Some nouns are irregular: man → men, woman → women, child → children, foot → feet, tooth → teeth, mouse → mice."}, {"type": "examples", "items": ["one apple – three apples", "one dish – two dishes", "one country – five countries", "one child – two children"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('80ea5f02-5dda-5b08-b3cc-e4243ae53e9b','650870b8-2789-56cb-b1f6-0e2f16f40171',0,'SORT_COLUMNS','Распределите существительные по способу образования множественного числа.',$j${"columns": [{"id": "c1", "label": "+ -s"}, {"id": "c2", "label": "+ -es"}, {"id": "c3", "label": "irregular"}], "items": [{"id": "i1", "label": "cat"}, {"id": "i2", "label": "book"}, {"id": "i3", "label": "glass"}, {"id": "i4", "label": "brush"}, {"id": "i5", "label": "man"}, {"id": "i6", "label": "tooth"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('80ea5f02-5dda-5b08-b3cc-e4243ae53e9b',$j${"placement": {"i1": "c1", "i2": "c1", "i3": "c2", "i4": "c2", "i5": "c3", "i6": "c3"}}$j$::jsonb,'');
