INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('dd43e3e5-76c7-5d1d-9ad3-86d014f82d03','a0000000-0000-4000-8000-000000000051','Блок 24. A/An – Some/Any',24,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('ee6a6baa-c9e1-5343-8dc0-a9fea5ca7b4d','dd43e3e5-76c7-5d1d-9ad3-86d014f82d03','A/An – Some/Any',0,'LESSON',70,$j$[{"type": "rule", "text": "We use a/an with singular countable nouns (a book, an apple). We use an before a vowel sound (an egg, an umbrella). We use some in affirmative sentences with plural countable and uncountable nouns (some apples, some water). We use any in negative sentences and questions (There aren't any biscuits. Is there any milk?)."}, {"type": "examples", "items": ["I have got an orange.", "There is some cheese in the fridge.", "There aren't any biscuits.", "Is there any sugar?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c7856db1-7f51-5351-bf78-891c65199a82','ee6a6baa-c9e1-5343-8dc0-a9fea5ca7b4d',0,'CHOOSE','Выберите a или an.',$j${"items": [{"before": "", "after": "egg", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "", "after": "banana", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "", "after": "umbrella", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "", "after": "house", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "", "after": "orange", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}]}$j$::jsonb,10);
