INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('775bd516-9d1f-5b8d-887a-152c102a2c45','ee6a6baa-c9e1-5343-8dc0-a9fea5ca7b4d',1,'CHOOSE','Выберите some или any.',$j${"items": [{"before": "There is", "after": "milk in the glass.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "There aren't", "after": "oranges.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "Is there", "after": "bread?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "I have got", "after": "friends here.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}]}$j$::jsonb,10);
