INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('79769834-aea1-5bc8-890d-f60152fdb3a8','a0000000-0000-4000-8000-000000000051','Блок 25. Much/Many – A lot of – A few/A little',25,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('62f0a1a7-232e-5ad2-a41d-1d7a7c352d4a','79769834-aea1-5bc8-890d-f60152fdb3a8','Much/Many – A lot of – A few/A little',0,'LESSON',70,$j$[{"type": "rule", "text": "We use many and a few with countable plural nouns (many books, a few eggs). We use much and a little with uncountable nouns (much money, a little water). We use a lot of with both in affirmative sentences. Much and many are usually used in questions and negatives. A few = some but not many; a little = some but not much."}, {"type": "examples", "items": ["How many apples are there?", "There isn't much milk.", "I have got a lot of friends.", "There are a few biscuits left.", "Add a little salt."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('55cb9dbe-a157-557d-a3a7-d7236989066d','62f0a1a7-232e-5ad2-a41d-1d7a7c352d4a',0,'CHOOSE','Выберите much или many.',$j${"items": [{"before": "How", "after": "sugar do you want?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "How", "after": "eggs are there?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "There isn't", "after": "juice.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "There aren't", "after": "chairs.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('55cb9dbe-a157-557d-a3a7-d7236989066d',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d4d36ffd-14ba-534c-827b-6eddb78f81ff','62f0a1a7-232e-5ad2-a41d-1d7a7c352d4a',1,'CHOOSE','Выберите a few или a little.',$j${"items": [{"before": "There are", "after": "apples in the bowl.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "I have", "after": "money.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "Add", "after": "salt to the soup.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "We need", "after": "eggs.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}]}$j$::jsonb,10);
