INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('55a0b95b-30be-5c97-9d31-7767f63cc99d','a0000000-0000-4000-8000-000000000051','Блок 26. Will / Be going to',26,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('e9150ed0-5c26-5853-870f-71c96f0395b4','55a0b95b-30be-5c97-9d31-7767f63cc99d','Will / Be going to',0,'LESSON',70,$j$[{"type": "rule", "text": "We use will (+ bare infinitive) for predictions about the future, on-the-spot decisions, promises, threats or warnings and offers. The short form is 'll and the negative is will not (won't)."}, {"type": "rule", "text": "We use be going to (+ bare infinitive) for future plans and intentions, and for predictions based on what we can see or know now."}, {"type": "examples", "items": ["I'll open the door for him. (on-the-spot decision)", "I promise I'll be there on time. (promise)", "Stop or I'll call the police! (threat)", "Look at those clouds! It's going to rain. (prediction from evidence)", "I'm going to visit my aunt next week. (plan/intention)"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('965bbdb0-30bc-5820-8cfe-09e53f395c40','e9150ed0-5c26-5853-870f-71c96f0395b4',0,'CHOOSE','Прочитайте предложения и определите, что они выражают: предсказание о будущем, угрозу/предупреждение, обещание или спонтанное решение.',$j${"items": [{"before": "I'm very hungry. I'll buy a sandwich.", "after": "", "options": [{"id": "o_a", "label": "prediction about the future"}, {"id": "o_b", "label": "threat or warning"}, {"id": "o_c", "label": "promise"}, {"id": "o_d", "label": "on-the-spot decision"}]}, {"before": "Don't worry. I'll call you when I get there.", "after": "", "options": [{"id": "o_a", "label": "prediction about the future"}, {"id": "o_b", "label": "threat or warning"}, {"id": "o_c", "label": "promise"}, {"id": "o_d", "label": "on-the-spot decision"}]}, {"before": "Mobile phones won't exist in 100 years.", "after": "", "options": [{"id": "o_a", "label": "prediction about the future"}, {"id": "o_b", "label": "threat or warning"}, {"id": "o_c", "label": "promise"}, {"id": "o_d", "label": "on-the-spot decision"}]}, {"before": "She'll probably be late tonight.", "after": "", "options": [{"id": "o_a", "label": "prediction about the future"}, {"id": "o_b", "label": "threat or warning"}, {"id": "o_c", "label": "promise"}, {"id": "o_d", "label": "on-the-spot decision"}]}, {"before": "Is that Joe? I'll open the door for him.", "after": "", "options": [{"id": "o_a", "label": "prediction about the future"}, {"id": "o_b", "label": "threat or warning"}, {"id": "o_c", "label": "promise"}, {"id": "o_d", "label": "on-the-spot decision"}]}, {"before": "I think you will like Tokyo very much.", "after": "", "options": [{"id": "o_a", "label": "prediction about the future"}, {"id": "o_b", "label": "threat or warning"}, {"id": "o_c", "label": "promise"}, {"id": "o_d", "label": "on-the-spot decision"}]}, {"before": "I'll do my best to be there on time.", "after": "", "options": [{"id": "o_a", "label": "prediction about the future"}, {"id": "o_b", "label": "threat or warning"}, {"id": "o_c", "label": "promise"}, {"id": "o_d", "label": "on-the-spot decision"}]}, {"before": "Stop talking or I'll send you to the headmaster.", "after": "", "options": [{"id": "o_a", "label": "prediction about the future"}, {"id": "o_b", "label": "threat or warning"}, {"id": "o_c", "label": "promise"}, {"id": "o_d", "label": "on-the-spot decision"}]}, {"before": "I think I'll go to the cinema tonight.", "after": "", "options": [{"id": "o_a", "label": "prediction about the future"}, {"id": "o_b", "label": "threat or warning"}, {"id": "o_c", "label": "promise"}, {"id": "o_d", "label": "on-the-spot decision"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('965bbdb0-30bc-5820-8cfe-09e53f395c40',$j${"items": [{"correctId": "o_d"}, {"correctId": "o_c"}, {"correctId": "o_a"}, {"correctId": "o_a"}, {"correctId": "o_d"}, {"correctId": "o_a"}, {"correctId": "o_c"}, {"correctId": "o_b"}, {"correctId": "o_d"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('7a275c8f-0af8-5509-b95b-b36f56e88d70','e9150ed0-5c26-5853-870f-71c96f0395b4',1,'MATCH_PAIRS','Соотнесите части предложений, как в примере.',$j${"left": [{"id": "l1", "label": "Set the alarm for 6 or you …… late."}, {"id": "l2", "label": "I'm afraid she …… to the party tomorrow."}, {"id": "l3", "label": "Clean up your mess or Mum …… very angry."}, {"id": "l4", "label": "I need to borrow a book. I …… to the library."}, {"id": "l5", "label": "She believes he …… the race."}, {"id": "l6", "label": "It's very cold. I …… the window."}, {"id": "l7", "label": "I'm tired. I …… a nap."}, {"id": "l8", "label": "I promise. I …… you as soon as I arrive."}], "right": [{"id": "r_a", "label": "will be"}, {"id": "r_b", "label": "'ll get"}, {"id": "r_c", "label": "'ll close"}, {"id": "r_d", "label": "'ll call"}, {"id": "r_e", "label": "will win"}, {"id": "r_f", "label": "won't come"}, {"id": "r_g", "label": "'ll take"}, {"id": "r_h", "label": "'ll go"}]}$j$::jsonb,10);
