INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f2140b0c-d07d-5e3c-bb4b-b2ba312eaab2','e9150ed0-5c26-5853-870f-71c96f0395b4',6,'FILL_BLANK','Заполните пропуски формой will или be going to с глаголом в скобках.',$j${"items": [{"before": "You", "after": "your back if you do. (hurt)"}, {"before": "I", "after": "a picnic with my friends. (have)"}, {"before": "The phone's ringing. I", "after": "it! (get)"}, {"before": "I", "after": "some tea instead, please. (have)"}, {"before": "What", "after": "with her lottery money? (Sally/do)"}, {"before": "She", "after": "a new flat. (buy)"}, {"before": "Where", "after": "your holiday? (you/spend)"}, {"before": "I'm afraid I", "after": "on holiday this year. (not/go)"}, {"before": "Look at that tree! Oh, no! It", "after": "down. (fall)"}]}$j$::jsonb,10);
