INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('44ac68cb-2f51-501e-8972-b752e20e3457','e9150ed0-5c26-5853-870f-71c96f0395b4',7,'CHOOSE','Подчеркните правильный вариант.',$j${"items": [{"before": "Now that she has enough money, I'm sure she", "after": "a new car.", "options": [{"id": "o1", "label": "is going to buy"}, {"id": "o2", "label": "will buy"}]}, {"before": "It's very hot today. I", "after": "to the beach after lunch.", "options": [{"id": "o1", "label": "am going to go"}, {"id": "o2", "label": "'ll go"}]}, {"before": "She", "after": "us when she arrives in Paris.", "options": [{"id": "o1", "label": "is going to call"}, {"id": "o2", "label": "will call"}]}, {"before": "Martin", "after": "a great doctor one day.", "options": [{"id": "o1", "label": "is going to become"}, {"id": "o2", "label": "will become"}]}, {"before": "I promise I", "after": "back on time.", "options": [{"id": "o1", "label": "'ll be"}, {"id": "o2", "label": "am going to be"}]}, {"before": "Now that she is 22 years old, she", "after": "on her own.", "options": [{"id": "o1", "label": "is going to live"}, {"id": "o2", "label": "'ll live"}]}, {"before": "You", "after": "tired if you stay up all night.", "options": [{"id": "o1", "label": "are going to be"}, {"id": "o2", "label": "will be"}]}, {"before": "I studied very hard. I'm sure I", "after": "excellent grades.", "options": [{"id": "o1", "label": "will get"}, {"id": "o2", "label": "am going to get"}]}, {"before": "Andrew", "after": "to New York tomorrow evening.", "options": [{"id": "o1", "label": "is going to drive"}, {"id": "o2", "label": "will drive"}]}, {"before": "Look! She", "after": "!", "options": [{"id": "o1", "label": "will fall down"}, {"id": "o2", "label": "is going to fall down"}]}, {"before": "I think I", "after": "to bed.", "options": [{"id": "o1", "label": "am going to go"}, {"id": "o2", "label": "'ll go"}]}, {"before": "It's very quiet in here. I", "after": "on the radio.", "options": [{"id": "o1", "label": "will turn"}, {"id": "o2", "label": "am going to turn"}]}, {"before": "", "after": "the rubbish, please?", "options": [{"id": "o1", "label": "Will you take out"}, {"id": "o2", "label": "Are you going to take out"}]}, {"before": "Life", "after": "better in fifty years from now.", "options": [{"id": "o1", "label": "will be"}, {"id": "o2", "label": "is going to be"}]}]}$j$::jsonb,10);
