INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4a7108f1-f647-5a4b-9d95-4af227c98de4','e9150ed0-5c26-5853-870f-71c96f0395b4',8,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "I", "after": "learn tango one day.", "options": [{"id": "o1", "label": "am going to"}, {"id": "o2", "label": "will"}]}, {"before": "John and Liz", "after": "buy a new car next week.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "are going to"}]}, {"before": "Don't worry, Peter. I", "after": "help you with your homework!", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "am going to"}]}, {"before": "My teacher thinks I", "after": "be a great dancer.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "am going to"}]}, {"before": "This dress is gorgeous. I", "after": "buy it.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "am going to"}]}, {"before": "Stop right there or I", "after": "call the police!", "options": [{"id": "o1", "label": "am going to"}, {"id": "o2", "label": "will"}]}, {"before": "I'm sure she", "after": "be on time for the meeting.", "options": [{"id": "o1", "label": "is going to"}, {"id": "o2", "label": "will"}]}, {"before": "We", "after": "make a cake this afternoon.", "options": [{"id": "o1", "label": "are going to"}, {"id": "o2", "label": "will"}]}, {"before": "Next summer, I", "after": "travel to India.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "am going to"}]}, {"before": "", "after": "have a party for your next birthday?", "options": [{"id": "o1", "label": "Will you"}, {"id": "o2", "label": "Are you going to"}]}, {"before": "After lunch, Paul", "after": "do the shopping.", "options": [{"id": "o1", "label": "going to"}, {"id": "o2", "label": "will probably"}]}, {"before": "The alarm has gone off.", "after": "switch it off?", "options": [{"id": "o1", "label": "Are you going to"}, {"id": "o2", "label": "Will you"}]}, {"before": "I don't know when he", "after": "be back.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "is going to"}]}, {"before": "I'm sure we", "after": "meet again.", "options": [{"id": "o1", "label": "are going to"}, {"id": "o2", "label": "will"}]}, {"before": "We", "after": "visit Japan one day.", "options": [{"id": "o1", "label": "are going to"}, {"id": "o2", "label": "will"}]}, {"before": "She studies very hard. She", "after": "get excellent grades.", "options": [{"id": "o1", "label": "is going to"}, {"id": "o2", "label": "will to"}]}]}$j$::jsonb,10);
