INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('bd7dcaba-87b7-5073-9b87-67503385fbea','a0000000-0000-4000-8000-000000000051','Блок 27. Must / Mustn''t - Can / Can''t - Have to / Don''t have to',27,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b55894a4-8f6e-54d9-aea9-5ebbaa0eeb10','bd7dcaba-87b7-5073-9b87-67503385fbea','Must / Mustn''t - Can / Can''t - Have to / Don''t have to',0,'LESSON',70,$j$[{"type": "rule", "text": "We use must (+ bare infinitive) to express obligation or strong necessity. We use mustn't (must not) to express prohibition — that something is not allowed."}, {"type": "rule", "text": "We use can to express ability, permission or possibility, and can't (cannot) to express inability or that something is not allowed."}, {"type": "rule", "text": "We use have to / has to to express obligation (often from outside rules). We use don't have to / doesn't have to to show that there is no obligation or necessity."}, {"type": "examples", "items": ["You must wear a seatbelt in the car.", "You mustn't smoke in the restaurant.", "I can swim but I can't ski.", "She has to wear a uniform at work.", "We don't have to get up early on Sundays."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('42e7c724-4b5f-585c-8ccc-00f0c840e568','b55894a4-8f6e-54d9-aea9-5ebbaa0eeb10',0,'FILL_BLANK','Заполните пропуски словами can или can''t.',$j${"items": [{"before": "Marcia", "after": "go to school today; she's got the flu."}, {"before": "She", "after": "play the guitar very well."}, {"before": "You", "after": "borrow my laptop. I'm not using it right now."}, {"before": "I", "after": "do my maths homework. Can you help me?"}, {"before": "You", "after": "buy some very nice clothes in this shop."}, {"before": "You", "after": "use your mobile phone in class."}, {"before": "Mark is twelve; he", "after": "drive his dad's car."}, {"before": "Susie", "after": "draw very well."}, {"before": "You", "after": "be late for school. Your teacher will be angry."}, {"before": "Grace is only four years old. She", "after": "read yet."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('42e7c724-4b5f-585c-8ccc-00f0c840e568',$j${"items": [{"accept": ["can't", "cannot"]}, {"accept": ["can"]}, {"accept": ["can"]}, {"accept": ["can't", "cannot"]}, {"accept": ["can"]}, {"accept": ["can't", "cannot"]}, {"accept": ["can't", "cannot"]}, {"accept": ["can"]}, {"accept": ["can't", "cannot"]}, {"accept": ["can't", "cannot"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('51907df2-7171-5da8-8c46-e29d73032766','b55894a4-8f6e-54d9-aea9-5ebbaa0eeb10',1,'FILL_BLANK','Заполните пропуски: have to / has to или don''t / doesn''t have to.',$j${"items": [{"before": "Kevin is ill; he", "after": "go to the doctor."}, {"before": "You", "after": "wash the dishes; I'll do it."}, {"before": "Mum", "after": "cook for the children. They'll be home soon."}, {"before": "You", "after": "bring your laptop. We can use mine."}, {"before": "There is a lot of work to do; we", "after": "work till late at night."}, {"before": "Nicole is a nurse; she", "after": "wear a uniform at work."}, {"before": "It's Sunday; we", "after": "go to school today."}, {"before": "It's Susan's birthday; we", "after": "buy her a present."}, {"before": "We've got enough time; we", "after": "hurry."}, {"before": "I'm going home; I", "after": "feed the dog."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('51907df2-7171-5da8-8c46-e29d73032766',$j${"items": [{"accept": ["has to"]}, {"accept": ["don't have to", "do not have to"]}, {"accept": ["has to"]}, {"accept": ["don't have to", "do not have to"]}, {"accept": ["have to"]}, {"accept": ["has to"]}, {"accept": ["don't have to", "do not have to"]}, {"accept": ["have to"]}, {"accept": ["don't have to", "do not have to"]}, {"accept": ["have to"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('de99f05d-d3f6-5755-8b4d-1e96b8e86654','b55894a4-8f6e-54d9-aea9-5ebbaa0eeb10',2,'CHOOSE','Подчеркните правильный вариант.',$j${"items": [{"before": "You", "after": "wash your hands before you eat.", "options": [{"id": "o1", "label": "must"}, {"id": "o2", "label": "can"}]}, {"before": "Sally", "after": "cook very well.", "options": [{"id": "o1", "label": "mustn't"}, {"id": "o2", "label": "can't"}]}, {"before": "You", "after": "wait for a table.", "options": [{"id": "o1", "label": "don't have to"}, {"id": "o2", "label": "can't"}]}, {"before": "You", "after": "smoke in English restaurants.", "options": [{"id": "o1", "label": "don't have to"}, {"id": "o2", "label": "mustn't"}]}, {"before": "Susan", "after": "clean her house.", "options": [{"id": "o1", "label": "can't"}, {"id": "o2", "label": "doesn't have to"}]}]}$j$::jsonb,10);
