INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2b16b8b6-c2b0-5285-a099-c5789aca613b','b55894a4-8f6e-54d9-aea9-5ebbaa0eeb10',3,'CHOOSE','Выберите правильный вариант (повторение).',$j${"items": [{"before": "We have", "after": "vegetables left. Let's make a soup.", "options": [{"id": "o1", "label": "a little"}, {"id": "o2", "label": "a few"}, {"id": "o3", "label": "a lot"}]}, {"before": "", "after": "is Mark? — 'My brother's best friend.'", "options": [{"id": "o1", "label": "How"}, {"id": "o2", "label": "Who"}, {"id": "o3", "label": "Whose"}]}, {"before": "We", "after": "go inside. It's not safe.", "options": [{"id": "o1", "label": "must"}, {"id": "o2", "label": "mustn't"}, {"id": "o3", "label": "can"}]}, {"before": "He always", "after": "up early in the morning.", "options": [{"id": "o1", "label": "gets"}, {"id": "o2", "label": "get"}, {"id": "o3", "label": "is getting"}]}, {"before": "I'm really thirsty. I", "after": "some orange juice.", "options": [{"id": "o1", "label": "will get"}, {"id": "o2", "label": "am going to get"}, {"id": "o3", "label": "get"}]}, {"before": "This is", "after": "apple pie.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}, {"id": "o3", "label": "the"}]}, {"before": "That's not Bill's car.", "after": "car is blue.", "options": [{"id": "o1", "label": "Him"}, {"id": "o2", "label": "His"}, {"id": "o3", "label": "He"}]}, {"before": "Would you like", "after": "ice cream?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}, {"id": "o3", "label": "a few"}]}, {"before": "There", "after": "any bananas.", "options": [{"id": "o1", "label": "isn't"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "aren't"}]}, {"before": "I", "after": "work on Sundays. The office is not open.", "options": [{"id": "o1", "label": "never"}, {"id": "o2", "label": "sometimes"}, {"id": "o3", "label": "always"}]}, {"before": "Mark is older", "after": "his brother.", "options": [{"id": "o1", "label": "of"}, {"id": "o2", "label": "than"}, {"id": "o3", "label": "from"}]}, {"before": "He loves", "after": "golf in the summer.", "options": [{"id": "o1", "label": "play"}, {"id": "o2", "label": "to playing"}, {"id": "o3", "label": "playing"}]}, {"before": "It's sunny outside. You", "after": "take an umbrella with you.", "options": [{"id": "o1", "label": "mustn't"}, {"id": "o2", "label": "don't have to"}, {"id": "o3", "label": "can't"}]}, {"before": "The piano is", "after": "the window.", "options": [{"id": "o1", "label": "between"}, {"id": "o2", "label": "in front of"}, {"id": "o3", "label": "behind"}]}, {"before": "My sister's birthday is", "after": "10th February.", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "in"}, {"id": "o3", "label": "at"}]}, {"before": "It's", "after": "sunny today. It looks like it is going to rain.", "options": [{"id": "o1", "label": "extremely"}, {"id": "o2", "label": "not very"}, {"id": "o3", "label": "quite"}]}, {"before": "How", "after": "sugar do you want?", "options": [{"id": "o1", "label": "many"}, {"id": "o2", "label": "much"}, {"id": "o3", "label": "long"}]}, {"before": "Can I have", "after": "slice of pizza, please?", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}, {"id": "o3", "label": "any"}]}, {"before": "", "after": "like green tea?", "options": [{"id": "o1", "label": "Will you"}, {"id": "o2", "label": "Are you going to"}, {"id": "o3", "label": "Do you"}]}, {"before": "You", "after": "ride a bike without a helmet.", "options": [{"id": "o1", "label": "mustn't"}, {"id": "o2", "label": "must"}, {"id": "o3", "label": "don't have to"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('2b16b8b6-c2b0-5285-a099-c5789aca613b',$j${"items": [{"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o3"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o3"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o3"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('ee61a515-3368-59ae-a74f-cc94526a7f5b','a0000000-0000-4000-8000-000000000051','Блок 28. Was / Were',28,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('8cc17a3d-a5b3-5c0e-b437-90a14d3694e6','ee61a515-3368-59ae-a74f-cc94526a7f5b','Was / Were',0,'LESSON',70,$j$[{"type": "rule", "text": "Was and were are the past simple forms of the verb be. We use was with I, he, she and it, and were with you, we and they."}, {"type": "rule", "text": "The negative is was not (wasn't) and were not (weren't). To make questions we put was/were before the subject: Was he ...? Were they ...?"}, {"type": "examples", "items": ["I was at home yesterday.", "They were very happy.", "She wasn't at school last week.", "Were you tired? — Yes, I was. / No, I wasn't."]}]$j$::jsonb);
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('6e179d75-4f7b-5ee1-9959-119a2dc90edc','a0000000-0000-4000-8000-000000000051','Блок 29. Had',29,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('f1e529d9-da88-5ee4-bcca-903509341a5f','6e179d75-4f7b-5ee1-9959-119a2dc90edc','Had',0,'LESSON',70,$j$[{"type": "rule", "text": "Had is the past simple of the verb have (has). We use had with all persons to talk about possession, experiences or things we had in the past."}, {"type": "rule", "text": "The negative and question forms use did: didn't have and Did ... have ...?"}, {"type": "examples", "items": ["I had a bike when I was ten.", "She had long hair as a child.", "We didn't have any money.", "Did you have a good time? — Yes, I did."]}]$j$::jsonb);
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('79f3de94-f4e7-5eb7-849c-587e3d975380','a0000000-0000-4000-8000-000000000051','Блок 30. Could',30,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('45798900-d94c-5e91-a2ec-170f88605506','79f3de94-f4e7-5eb7-849c-587e3d975380','Could',0,'LESSON',70,$j$[{"type": "rule", "text": "Could is the past form of can. We use could to talk about ability in the past and to make polite requests or offers."}, {"type": "rule", "text": "The negative is couldn't (could not). To make questions we put could before the subject: Could you ...?"}, {"type": "examples", "items": ["When I was five, I could swim.", "She couldn't ride a bike.", "Could you help me, please?", "Could I open the window?"]}]$j$::jsonb);
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('938b9f8f-c144-53e8-ad92-aed15632d4ae','a0000000-0000-4000-8000-000000000051','Блок 31. There was / There were',31,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('793e0530-dab1-5e54-abbf-f5ff05b158ba','938b9f8f-c144-53e8-ad92-aed15632d4ae','There was / There were',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'there was' with singular and uncountable nouns and 'there were' with plural nouns to talk about things that existed in the past."}, {"type": "rule", "text": "Negative: there wasn't / there weren't. Question: Was there ...? / Were there ...? Short answers: Yes, there was/were. No, there wasn't/weren't."}, {"type": "examples", "items": ["There was a clock on the wall.", "There were three books on the desk.", "Was there a party? Yes, there was.", "There weren't many people at the shop."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('780b8460-00e0-5f52-b0a0-900eda7592be','793e0530-dab1-5e54-abbf-f5ff05b158ba',0,'CHOOSE','Выберите was или were.',$j${"items": [{"before": "There", "after": "a bicycle in the garage.", "options": [{"id": "o1", "label": "was"}, {"id": "o2", "label": "were"}]}, {"before": "There", "after": "two robots on the shelf.", "options": [{"id": "o1", "label": "was"}, {"id": "o2", "label": "were"}]}, {"before": "There", "after": "some newspapers on the table.", "options": [{"id": "o1", "label": "was"}, {"id": "o2", "label": "were"}]}, {"before": "There", "after": "a laptop on the desk.", "options": [{"id": "o1", "label": "was"}, {"id": "o2", "label": "were"}]}, {"before": "There", "after": "a hat on the chair.", "options": [{"id": "o1", "label": "was"}, {"id": "o2", "label": "were"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('780b8460-00e0-5f52-b0a0-900eda7592be',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c1e464c0-55c2-52d9-b7bb-cc64734481d5','793e0530-dab1-5e54-abbf-f5ff05b158ba',1,'CHOOSE','Выберите правильную отрицательную форму: wasn''t или weren''t.',$j${"items": [{"before": "There", "after": "any people in the room.", "options": [{"id": "o1", "label": "wasn't"}, {"id": "o2", "label": "weren't"}]}, {"before": "There", "after": "a clock in the kitchen.", "options": [{"id": "o1", "label": "wasn't"}, {"id": "o2", "label": "weren't"}]}, {"before": "There", "after": "many students in the class.", "options": [{"id": "o1", "label": "wasn't"}, {"id": "o2", "label": "weren't"}]}]}$j$::jsonb,10);
