INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('63516c60-522f-587a-9455-5218735be9bb','a0000000-0000-4000-8000-000000000051','Блок 32. Past Simple (regular verbs)',32,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('86a8aa70-2c98-5b1b-b7a5-12aa282d8880','63516c60-522f-587a-9455-5218735be9bb','Past Simple (regular verbs)',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the past simple of regular verbs by adding -ed to the base form (work → worked). Verbs ending in -e add -d (live → lived). Verbs ending in consonant + y change y to -ied (study → studied). Short verbs ending in consonant-vowel-consonant double the last consonant (stop → stopped)."}, {"type": "rule", "text": "The past simple is the same for all persons. Negative: didn't + base verb. Question: Did + subject + base verb? Short answers: Yes, I did. / No, I didn't."}, {"type": "examples", "items": ["He played football yesterday.", "They didn't watch TV.", "Did you call me? Yes, I did."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('1136de5d-8f74-5e6b-9849-6ea9c54f466a','86a8aa70-2c98-5b1b-b7a5-12aa282d8880',0,'FILL_BLANK','Поставьте глаголы в скобках в past simple (текст об Эль Греко).',$j${"items": [{"before": "El Greco", "after": "(live) on the island of Crete, in Greece."}, {"before": "He", "after": "(train) to be an artist."}, {"before": "At the age of 26, he", "after": "(travel) to Venice."}, {"before": "He", "after": "(move) to Rome."}, {"before": "He", "after": "(open) his own workshop."}, {"before": "He", "after": "(learn) many new skills there."}, {"before": "Eventually he", "after": "(decide) to go to Spain."}, {"before": "The people there", "after": "(love) his work."}, {"before": "He", "after": "(stay) there for many years."}, {"before": "He", "after": "(die) in 1614."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('1136de5d-8f74-5e6b-9849-6ea9c54f466a',$j${"items": [{"accept": ["lived"]}, {"accept": ["trained"]}, {"accept": ["travelled", "traveled"]}, {"accept": ["moved"]}, {"accept": ["opened"]}, {"accept": ["learned", "learnt"]}, {"accept": ["decided"]}, {"accept": ["loved"]}, {"accept": ["stayed"]}, {"accept": ["died"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c65ee2a1-81b6-542e-89eb-34d36f0118b3','86a8aa70-2c98-5b1b-b7a5-12aa282d8880',1,'MATCH_PAIRS','Соедините вопросы с ответами.',$j${"left": [{"id": "l1", "label": "What time did you return home from school yesterday?"}, {"id": "l2", "label": "Where did Mark play basketball last Tuesday?"}, {"id": "l3", "label": "What did your mum cook for dinner last night?"}, {"id": "l4", "label": "What did you study yesterday morning?"}, {"id": "l5", "label": "Who did you visit last weekend?"}, {"id": "l6", "label": "When did Paul travel to France?"}, {"id": "l7", "label": "How many emails did Sarah receive last month?"}, {"id": "l8", "label": "When did Anna start learning English?"}], "right": [{"id": "r1", "label": "At 4 o'clock."}, {"id": "r2", "label": "At the park."}, {"id": "r3", "label": "Chicken and rice."}, {"id": "r4", "label": "Maths."}, {"id": "r5", "label": "Grandma and granddad."}, {"id": "r6", "label": "Last month."}, {"id": "r7", "label": "Eight."}, {"id": "r8", "label": "When she was 7 years old."}]}$j$::jsonb,10);
