INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('810301b1-a3e6-5aac-96b1-1d9944398836','86a8aa70-2c98-5b1b-b7a5-12aa282d8880',2,'CHOOSE','Выберите правильную форму past simple.',$j${"items": [{"before": "stop →", "after": "", "options": [{"id": "o1", "label": "stopped"}, {"id": "o2", "label": "stoped"}]}, {"before": "study →", "after": "", "options": [{"id": "o1", "label": "studyed"}, {"id": "o2", "label": "studied"}]}, {"before": "play →", "after": "", "options": [{"id": "o1", "label": "played"}, {"id": "o2", "label": "plaied"}]}, {"before": "carry →", "after": "", "options": [{"id": "o1", "label": "carryed"}, {"id": "o2", "label": "carried"}]}, {"before": "live →", "after": "", "options": [{"id": "o1", "label": "lived"}, {"id": "o2", "label": "livd"}]}]}$j$::jsonb,10);
