INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('84d0b466-4ddc-5cdd-aabe-e3271d74bcd6','a0000000-0000-4000-8000-000000000051','Блок 33. Past Simple (irregular verbs)',33,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('fe231104-7384-51f8-8574-3defe0f2c44e','84d0b466-4ddc-5cdd-aabe-e3271d74bcd6','Past Simple (irregular verbs)',0,'LESSON',70,$j$[{"type": "rule", "text": "Many common verbs are irregular in the past simple and do not take -ed. You must learn their forms (go → went, have → had, see → saw, buy → bought, make → made)."}, {"type": "rule", "text": "In negatives and questions the base form is used with didn't / did: I didn't go. Did you go? The irregular form appears only in the affirmative."}, {"type": "examples", "items": ["I went to the shops.", "She had a sandwich.", "Did you see the film? No, I didn't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6e597bcb-d597-563d-9b70-f901aaf27961','fe231104-7384-51f8-8574-3defe0f2c44e',0,'MATCH_PAIRS','Соедините глаголы с их формой past simple.',$j${"left": [{"id": "l1", "label": "go"}, {"id": "l2", "label": "have"}, {"id": "l3", "label": "see"}, {"id": "l4", "label": "buy"}, {"id": "l5", "label": "make"}, {"id": "l6", "label": "take"}, {"id": "l7", "label": "come"}, {"id": "l8", "label": "write"}, {"id": "l9", "label": "spend"}, {"id": "l10", "label": "begin"}], "right": [{"id": "r1", "label": "went"}, {"id": "r2", "label": "had"}, {"id": "r3", "label": "saw"}, {"id": "r4", "label": "bought"}, {"id": "r5", "label": "made"}, {"id": "r6", "label": "took"}, {"id": "r7", "label": "came"}, {"id": "r8", "label": "wrote"}, {"id": "r9", "label": "spent"}, {"id": "r10", "label": "began"}]}$j$::jsonb,10);
